import {
  useEffect,
  useState
} from "react";

import api
from "../../api/axios";

function StoreList() {

  const [stores,
    setStores] =
    useState([]);

  const [search,
    setSearch] =
    useState("");

  useEffect(() => {

    fetchStores();

  }, []);

  const fetchStores =
  async () => {

    try {

      const response =
      await api.get(
        "/stores"
      );

      setStores(
        response.data.stores
      );

    }
    catch(error){

      console.log(error);

    }
  };

  const submitRating =
  async (
    storeId,
    rating
  ) => {

    try {

      await api.post(
        "/ratings",
        {
          storeId,
          rating
        }
      );

      alert(
        "Rating Saved"
      );

      fetchStores();

    }
    catch(error){

      console.log(error);

    }
  };

  const filteredStores =
  stores.filter(
    (store)=>
      store.name
      .toLowerCase()
      .includes(
        search.toLowerCase()
      )
  );

  return (

    <div>

      <h1>
        Store List
      </h1>

      <input
        type="text"
        placeholder="Search Store"
        value={search}
        onChange={(e)=>
          setSearch(
            e.target.value
          )
        }
      />

      <hr/>

      {
        filteredStores.map(
          (store)=>(
            <div
              key={store.id}
            >

              <h3>
                {store.name}
              </h3>

              <p>
                {store.address}
              </p>

              <p>
                Overall Rating:
                {
                  store.averageRating
                  || 0
                }
              </p>

              <select
                onChange={(e)=>
                  submitRating(
                    store.id,
                    Number(
                      e.target.value
                    )
                  )
                }
              >

                <option>
                  Rate
                </option>

                <option value="1">
                  1
                </option>

                <option value="2">
                  2
                </option>

                <option value="3">
                  3
                </option>

                <option value="4">
                  4
                </option>

                <option value="5">
                  5
                </option>

              </select>

              <hr/>

            </div>
          )
        )
      }

    </div>
  );
}

export default StoreList;
